-- CSC blog yazıları (herkese açık içerik; fiyat yok). Supabase SQL Editor'da çalıştırılır.
select setval(pg_get_serial_sequence('public.blog_yazilari','id'), (select max(id) from public.blog_yazilari)); select (select count(*) from public.ilaclar) ilac, (select count(*) from public.ilac_fiyatlari) fiyat, (select count(*) from public.blog_yazilari) blog;
